import heapq

def stable_matching(proposers, receivers):
    # Precompute each receiver's ranking of proposers for quick comparison.
    rank = {
        receiver: {proposer: i for i, proposer in enumerate(pref)}
        for receiver, pref in receivers.items()
    }

    # Track the next receiver each proposer will propose to.
    next_idx = {proposer: 0 for proposer in proposers}

    # Current matches: receiver -> proposer and proposer -> receiver
    receiver_match = {}
    proposer_match = {}

    # All proposers start free; process them in plain string order using a min-heap.
    free = list(proposers.keys())
    heapq.heapify(free)

    while free:
        proposer = heapq.heappop(free)
        pref_list = proposers[proposer]

        # Propose to the next receiver on the proposer's list.
        receiver = pref_list[next_idx[proposer]]
        next_idx[proposer] += 1

        if receiver not in receiver_match:
            # Receiver is free, so they accept.
            receiver_match[receiver] = proposer
            proposer_match[proposer] = receiver
        else:
            current = receiver_match[receiver]

            # If the receiver prefers the new proposer, switch.
            if rank[receiver][proposer] < rank[receiver][current]:
                receiver_match[receiver] = proposer
                proposer_match[proposer] = receiver

                # The previous proposer becomes free.
                proposer_match.pop(current, None)
                heapq.heappush(free, current)
            else:
                # Rejected; proposer stays free and will propose to the next receiver later.
                heapq.heappush(free, proposer)

    return proposer_match
